#!/usr/bin/env python3
"""Regenerate static/lang/bg.js from static/lang/bg.json.

bg.js is the dictionary used when the UI is opened straight from disk (file://, the demo
mode of static/index.html), where fetch() of JSON is blocked. Run after editing bg.json.
"""
import json, pathlib

root = pathlib.Path(__file__).parent / 'static' / 'lang'
data = json.loads((root / 'bg.json').read_text(encoding='utf8'))
body = json.dumps(data, ensure_ascii=False, indent=1)
(root / 'bg.js').write_text(
    '// generated by gen_lang_fallback.py from bg.json - do not edit\n'
    'window.__I18N = window.__I18N || {}; window.__I18N.bg = ' + body + ';\n',
    encoding='utf8')
print('wrote', root / 'bg.js')
